package jp.haruto.dreamcamera;
import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import android.view.*;import android.widget.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.*;import androidx.camera.core.*;import androidx.camera.lifecycle.ProcessCameraProvider;import androidx.camera.view.PreviewView;import androidx.core.content.ContextCompat;import androidx.exifinterface.media.ExifInterface;import com.google.android.material.dialog.MaterialAlertDialogBuilder;import com.google.common.util.concurrent.ListenableFuture;import java.io.*;import java.text.SimpleDateFormat;import java.util.*;import java.util.concurrent.*;

public class MainActivity extends AppCompatActivity{
 PreviewView preview;ImageCapture capture;ArrayList<Preset>presets;Preset current;LinearLayout chips;TextView title,status;ExecutorService io=Executors.newSingleThreadExecutor();
 ActivityResultLauncher<String>permission=registerForActivityResult(new ActivityResultContracts.RequestPermission(),ok->{if(ok)startCamera();else status.setText("カメラ権限が必要です");});
 public void onCreate(Bundle b){super.onCreate(b);buildUi();presets=PresetStore.load(this);current=presets.get(1);refreshChips();applyPreview();if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)startCamera();else permission.launch(Manifest.permission.CAMERA);}
 void buildUi(){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(9,7,13));preview=new PreviewView(this);preview.setImplementationMode(PreviewView.ImplementationMode.COMPATIBLE);preview.setScaleType(PreviewView.ScaleType.FILL_CENTER);root.addView(preview,new FrameLayout.LayoutParams(-1,-1));LinearLayout top=new LinearLayout(this);top.setPadding(28,48,20,12);top.setGravity(Gravity.CENTER_VERTICAL);title=new TextView(this);title.setText("Dream Camera");title.setTextColor(Color.WHITE);title.setTextSize(22);title.setTypeface(null,android.graphics.Typeface.BOLD);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button edit=button("調整・保存");edit.setOnClickListener(v->editor());top.addView(edit);FrameLayout.LayoutParams tp=new FrameLayout.LayoutParams(-1,-2,Gravity.TOP);root.addView(top,tp);LinearLayout bottom=new LinearLayout(this);bottom.setOrientation(LinearLayout.VERTICAL);bottom.setPadding(16,10,16,28);bottom.setBackgroundColor(0xB809070D);HorizontalScrollView scroll=new HorizontalScrollView(this);chips=new LinearLayout(this);chips.setOrientation(LinearLayout.HORIZONTAL);scroll.addView(chips);bottom.addView(scroll,new LinearLayout.LayoutParams(-1,-2));status=new TextView(this);status.setText("原本＋加工版を同時保存");status.setTextColor(0xFFD8CBE8);status.setGravity(Gravity.CENTER);status.setPadding(0,10,0,6);bottom.addView(status);Button shutter=button("●  撮影");shutter.setTextSize(20);shutter.setOnClickListener(v->shoot());bottom.addView(shutter,new LinearLayout.LayoutParams(-1,70));root.addView(bottom,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));setContentView(root);}
 Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);return b;}
 void refreshChips(){chips.removeAllViews();for(Preset p:presets){Button b=button(p.name);b.setOnClickListener(v->{current=p;applyPreview();refreshChips();});b.setAlpha(p==current?1:.62f);chips.addView(b);} }
 void applyPreview(){title.setText("Dream Camera  ·  "+current.name);RenderEffect color=RenderEffect.createColorFilterEffect(new ColorMatrixColorFilter(PhotoProcessor.matrix(current)));if(current.blur>1)preview.setRenderEffect(RenderEffect.createBlurEffect(current.blur/3,current.blur/3,color,Shader.TileMode.CLAMP));else preview.setRenderEffect(color);}
 void startCamera(){ListenableFuture<ProcessCameraProvider>f=ProcessCameraProvider.getInstance(this);f.addListener(()->{try{ProcessCameraProvider cp=f.get();Preview p=new Preview.Builder().build();p.setSurfaceProvider(preview.getSurfaceProvider());capture=new ImageCapture.Builder().setCaptureMode(ImageCapture.CAPTURE_MODE_MAXIMIZE_QUALITY).build();cp.unbindAll();cp.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,p,capture);}catch(Exception e){status.setText("カメラ開始エラー: "+e.getMessage());}},ContextCompat.getMainExecutor(this));}
 void shoot(){if(capture==null)return;status.setText("撮影・2枚を処理中…");File tmp=new File(getCacheDir(),"capture.jpg");capture.takePicture(new ImageCapture.OutputFileOptions.Builder(tmp).build(),io,new ImageCapture.OnImageSavedCallback(){public void onError(ImageCaptureException e){runOnUiThread(()->status.setText("撮影失敗: "+e.getMessage()));}public void onImageSaved(ImageCapture.OutputFileResults r){try{Bitmap raw=oriented(tmp);Bitmap fx=PhotoProcessor.apply(raw,current);String stamp=new SimpleDateFormat("yyyyMMdd_HHmmss",Locale.JAPAN).format(new Date());save(raw,"DC_"+stamp+"_ORIGINAL.jpg");save(fx,"DC_"+stamp+"_"+safe(current.name)+".jpg");tmp.delete();runOnUiThread(()->status.setText("保存しました：原本＋「"+current.name+"」"));}catch(Exception e){runOnUiThread(()->status.setText("保存失敗: "+e.getMessage()));}}});}
 Bitmap oriented(File f)throws Exception{Bitmap b=BitmapFactory.decodeFile(f.getAbsolutePath());int o=new ExifInterface(f).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL),d=o==6?90:o==3?180:o==8?270:0;if(d==0)return b;Matrix m=new Matrix();m.postRotate(d);return Bitmap.createBitmap(b,0,0,b.getWidth(),b.getHeight(),m,true);}
 void save(Bitmap b,String name)throws Exception{ContentValues v=new ContentValues();v.put(MediaStore.Images.Media.DISPLAY_NAME,name);v.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");v.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/DreamCamera");Uri u=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,v);try(OutputStream o=getContentResolver().openOutputStream(u)){b.compress(Bitmap.CompressFormat.JPEG,94,o);}}
 String safe(String s){return s.replaceAll("[^a-zA-Z0-9ぁ-んァ-ン一-龯_-]","_");}
 void editor(){Preset original=current,work=current.copy(current.name);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(36,0,36,0);EditText name=new EditText(this);name.setHint("プリセット名");name.setText(current.name+" Custom");box.addView(name);String[]keys=Preset.keys();float[]vals=work.vals();for(int i=0;i<keys.length;i++){int x=i;TextView label=new TextView(this);label.setText(keys[i]+"  "+Math.round(vals[i]));box.addView(label);SeekBar bar=new SeekBar(this);bar.setMax(200);bar.setProgress(Math.round(vals[i]+100));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean u){vals[x]=n-100;label.setText(keys[x]+"  "+(n-100));work.set(vals);current=work;applyPreview();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});box.addView(bar);}ScrollView sc=new ScrollView(this);sc.addView(box);new MaterialAlertDialogBuilder(this).setTitle("色味を作る").setView(sc).setNegativeButton("取消",(d,w)->{current=original;applyPreview();}).setPositiveButton("名前を付けて保存",(d,w)->{String n=name.getText().toString().trim();if(n.isEmpty())n="My Preset";work.name=n;presets.add(work);current=work;PresetStore.saveCustom(this,presets);refreshChips();applyPreview();}).show();}
 protected void onDestroy(){super.onDestroy();io.shutdown();}
}
